    'asterisk_settings.rtp_help_body' => 'Styr vilket portintervall som bär ljud (RTP) och om Asterisk avvisar ljud som kommer från en oväntad källa. Denna fil (<code>/etc/asterisk/rtp.conf</code>) genereras nu av panelen; manuella ändringar på servern går förlorade vid nästa ”Verkställ”.',
    'asterisk_settings.field_rtp_start' => 'RTP startport',
