    'sound_packs.help_title' => 'Asterisk-ljudpaket',
    'sound_packs.help_body' => 'Laddar ner och installerar Asterisks officiella systemmeddelanden och väntmusik från <code>downloads.asterisk.org</code>. Varje paket är ett språk i ett format; Asterisk spelar det format som matchar samtalets codec och omkodar annars (g722 för G.722, ulaw/alaw för operatörer).<br>- <strong>Core:</strong> systemmeddelanden, siffror, röstbrevlåda. <strong>Extra:</strong> ytterligare meddelanden; samma språks core-paket måste installeras först.<br>- <strong>Väntmusik (opsound):</strong> installeras i <code>/var/lib/asterisk/moh/opsound</code>; för att spela den, skapa en MOH-klass med namnet <strong>opsound</strong> på fliken Väntmusik.<br>- <strong>Turkiska (AiPBX):</strong> AiPBX egna turkiska meddelanden (GitHub-release, SHA256-verifierade); standardspråket är turkiska, så om de tas bort tystnar systemmeddelandena. Borttagning raderar endast de filer som paketet installerade.',
