    'system_update.help_body' => 'Uppdateringen säkerhetskopierar först databasen, inställningarna och Asterisk-konfigurationen, installerar sedan den nya versionen och testar att allt fungerar. Om något misslyckas återgår den automatiskt till den tidigare versionen. Asterisk startas om under uppdateringen: pågående samtal kopplas ner, så den startar inte medan samtal är aktiva. Den kan också köras på servern: <code>sudo aipbx-update</code>',
