    'certificates.help_title' => 'Certifikatguide',
    'certificates.help_body' => 'Portalen (HTTPS), WebRTC TURNS och SIP-TLS/WSS delar ett certifikat; ändringar här tillämpas på Apache, coturn och Asterisk samtidigt. <b>Let\'s Encrypt</b> är gratis och förnyas automatiskt; domänen måste peka på den här servern och port 80 måste kunna nås från internet. Om din organisation har ett certifikat kan du <b>ladda upp det</b> (PEM eller PFX); uppladdade certifikat förnyas inte automatiskt, så ladda upp ett nytt innan det går ut. Med ett <b>självsignerat</b> certifikat visar webbläsare en varning och TURNS fungerar inte i webbläsare: WebRTC-samtal bakom brandväggar kan sakna ljud.',
