    'queue_reports.title' => 'Rapportcenter för köer',
    'queue_reports.help_title' => 'Guide för köraporter',
    'queue_reports.help_body' => 'Varje samtal som går in i en kö räknas en gång. <b>Besvarade</b>: kopplade till en agent. <b>Förlorade</b>: uppringaren lade på under väntan eller kön nådde tidsgränsen. <b>Kort avbrott</b>: lade på inom %d sekunder; räknas inte in i servicenivån. <b>Servicenivå</b>: samtal besvarade inom målet, av alla samtal utom korta avbrott. <b>ASA</b>: genomsnittlig väntetid för besvarade samtal. <b>AHT</b>: genomsnittlig samtalstid. <b>Svarsfrekvens</b> (agent): hur ofta agenten svarade när kön ringde hen. <b>Återuppringning</b>: ett förlorat samtal räknas som löst när numret senare ringdes upp från en anknytning, eller ringde igen och besvarades. Data kommer från Asterisks kölogg; rapporten kan laddas ner som PDF eller Excel.',
