    'ai_tts.help_title' => 'Guide för moln-TTS',
    'ai_tts.help_body' => 'Omvandlar text till naturligt tal med molntjänster (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Lyssna på resultatet, ladda ner det som MP3 eller spara det som ett <b>meddelande</b> med ett klick: det konverteras till Asterisks format (8 kHz WAV) och läggs till i Ljud &amp; meddelanden för IVR, inkommande rutter och tidsvillkor (gäller efter Tillämpa). <b>Dessa tjänster är avgiftsbelagda</b> och debiterar per tecken; varje syntes sparas i historiken med sitt teckenantal. Åtkomstnycklar hämtas från respektive leverantörs konsol, lagras krypterade och visas aldrig mer på sidan.',
