    'mailtpl.invite_new.body' => '<p>Hej {name},</p><p>Ditt konto i växeln <strong>{brand}</strong> är klart. Ange ditt lösenord med knappen nedan för att logga in.</p>{account_details}{reset_button}<p>Om knappen inte fungerar öppnar du den här länken: {reset_link}</p>{mobile_section}<p><em>Lösenordslänken gäller i 48 timmar och fungerar en gång. Om du inte väntade dig det här meddelandet kontaktar du din systemadministratör.</em></p>',
