    'mailtpl.password_reset.body' => '<p>Hej {name},</p><p>En lösenordsåterställning har begärts för ditt konto <strong>{username}</strong>.</p>{reset_button}<p>Om knappen inte fungerar öppnar du den här länken: {reset_link}</p><p><em>Länken gäller i 30 minuter. Om du inte har begärt den kan du bortse från det här meddelandet; ditt lösenord förblir detsamma.</em></p>',
    'mailtpl.voicemail.subject' => 'Nytt röstmeddelande från {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hej {name},</p><p>Du har ett nytt meddelande i röstbrevlådan <strong>{mailbox}</strong>.</p><ul><li><strong>Från:</strong> {caller}</li><li><strong>Mottaget:</strong> {date}</li><li><strong>Längd:</strong> {duration}</li></ul><p>Om inspelningen är bifogad kan du spela upp den direkt här. Du kan också lyssna på den i portalen ({portal_link}) eller genom att ringa *97.</p>',
